INSERT INTO QAs (question, response, category_id) VALUES
('Qu''est-ce que l''ENCG Marrakech ?', 'École de l’Université Cadi Ayyad spécialisée dans la formation en commerce, gestion et management.', 1),
('Quelles sont les valeurs de l''ENCGM ?', 'Excellence, Noblesse, Collaboration, Générosité et Mouvement.', 1),
('Que sont les années préparatoires ?', 'Elles construisent un socle de compétences en économie, management, comptabilité, marketing, commerce, logistique, communication et outils digitaux.', 2),
('Je ne sais pas quelle filière choisir.', 'Je peux vous aider à identifier les filières correspondant à votre profil. Je vais vous poser quelques questions sur vos centres d’intérêt, vos points forts et votre projet.', 3),
('Quelle est la meilleure filière ?', 'Il n’existe pas une filière meilleure pour tous. Le choix dépend de vos intérêts, compétences, projet professionnel et préférences.', 3),
('Quelle filière choisir si j''aime les chiffres ?', 'Finance et Contrôle Audit et Conseil peuvent être des pistes pertinentes si vous aimez l’analyse, les chiffres et la rigueur. Je peux affiner avec quelques questions.', 3),
('Quelle filière choisir si j''aime le digital et l''IA ?', 'Marketing Digital est une piste particulièrement cohérente avec l’intérêt pour le digital, les données et l’IA. Business Administration peut aussi convenir si vous recherchez une approche transversale.', 3),
('Je veux travailler à l''international.', 'Commerce International est directement orienté vers les environnements internationaux. Business Administration et Purchasing & Supply Chain Management présentent également une dimension internationale selon les descriptifs.', 3),
('Qu''est-ce que la filière Finance ?', 'Analyse financière, marchés, risques, évaluation, investissement, modélisation et Fintech.', 4),
('Quelles compétences développe Finance ?', 'Analyse statistique et économétrique, logiciels financiers, programmation/codage notamment Python, décision stratégique, communication/négociation, éthique et conformité.', 5),
('Quels sont les débouchés de Finance ?', 'Responsable financier, analyste financier ou gestionnaire de portefeuille, responsable de gestion des risques, contrôleur de gestion ou auditeur financier, consultant, spécialiste Fintech et formation doctorale.', 6),
('Quelle est la langue d''enseignement de Finance ?', 'Français', 7),
('Quelles sont les conditions d''accès à Finance ?', 'Les Deux Années Préparatoires des Ecoles Nationales de Commerce et de Gestion ; spécialité Gestion commerce.', 8),
('À quel profil correspond Finance ?', 'Elle peut particulièrement convenir aux étudiants attirés par les dimensions suivantes : Analyse financière, marchés, risques, évaluation, investissement, modélisation et Fintech.', 3),
('Pourquoi choisir Finance ?', 'Analyse financière, marchés, risques, évaluation, investissement, modélisation et Fintech. Le choix doit être rapproché de votre profil et de votre projet professionnel.', 9),
('Qu''est-ce que la filière Contrôle Audit et Conseil ?', 'Audit, contrôle de gestion, révision comptable, contrôle interne, gestion des risques et conseil.', 4),
('Quelles compétences développe Contrôle Audit et Conseil ?', 'Évaluer le contrôle interne, identifier les risques et proposer des solutions, participer à une mission d’audit et de commissariat aux comptes, travailler en équipe et développer le sens critique.', 5),
('Quels sont les débouchés de Contrôle Audit et Conseil ?', 'Auditeur, contrôleur de gestion, responsable financier, consultant et formation doctorale.', 6),
('Quelle est la langue d''enseignement de Contrôle Audit et Conseil ?', 'Français', 7),
('Quelles sont les conditions d''accès à Contrôle Audit et Conseil ?', 'Les Deux Années Préparatoires des Ecoles Nationales de Commerce et de Gestion ; spécialité Commerce et gestion.', 8),
('À quel profil correspond Contrôle Audit et Conseil ?', 'Elle peut particulièrement convenir aux étudiants attirés par les dimensions suivantes : Audit, contrôle de gestion, révision comptable, contrôle interne, gestion des risques et conseil.', 3),
('Pourquoi choisir Contrôle Audit et Conseil ?', 'Audit, contrôle de gestion, révision comptable, contrôle interne, gestion des risques et conseil. Le choix doit être rapproché de votre profil et de votre projet professionnel.', 9),
('Qu''est-ce que la filière Marketing et Action Commerciale ?', 'Marketing, communication, vente, marketing relationnel, négociation, stratégie commerciale, e-marketing, CRM, études de marché et force de vente.', 4),
('Quelles compétences développe Marketing et Action Commerciale ?', 'Le descriptif met l’accent sur marketing, communication, vente, relation client, négociation et stratégie commerciale.', 5),
('Quels sont les débouchés de Marketing et Action Commerciale ?', 'Les débouchés précis doivent être repris du descriptif institutionnel validé ; ne pas les inventer.', 6),
('Quelle est la langue d''enseignement de Marketing et Action Commerciale ?', 'Français', 7),
('Quelles sont les conditions d''accès à Marketing et Action Commerciale ?', 'Les Deux Années Préparatoires des Ecoles Nationales de Commerce et de Gestion ; spécialité Commerce et gestion.', 8),
('À quel profil correspond Marketing et Action Commerciale ?', 'Elle peut particulièrement convenir aux étudiants attirés par les dimensions suivantes : Marketing, communication, vente, marketing relationnel, négociation, stratégie commerciale, e-marketing, CRM, études de marché et force de vente.', 3),
('Pourquoi choisir Marketing et Action Commerciale ?', 'Marketing, communication, vente, marketing relationnel, négociation, stratégie commerciale, e-marketing, CRM, études de marché et force de vente. Le choix doit être rapproché de votre profil et de votre projet professionnel.', 9),
('Qu''est-ce que la filière Marketing Digital ?', 'Marketing, commerce, communication, digital, web, innovation, Social CRM, influence, Big Data, IA, trafic, analyse web, community management et référencement.', 4),
('Quelles compétences développe Marketing Digital ?', 'Projets digitaux, e-CRM, e-business, connaissance client/tracking, stratégie web, e-marketing, community management et e-réputation.', 5),
('Quels sont les débouchés de Marketing Digital ?', 'Responsable de la stratégie digitale et autres métiers digitaux à reprendre précisément du descriptif validé.', 6),
('Quelle est la langue d''enseignement de Marketing Digital ?', 'Français', 7),
('Quelles sont les conditions d''accès à Marketing Digital ?', 'Les Deux Années Préparatoires des Ecoles Nationales de Commerce et de Gestion ; spécialité Commerce et gestion.', 8),
('À quel profil correspond Marketing Digital ?', 'Elle peut particulièrement convenir aux étudiants attirés par les dimensions suivantes : Marketing, commerce, communication, digital, web, innovation, Social CRM, influence, Big Data, IA, trafic, analyse web, community management et référencement.', 3),
('Pourquoi choisir Marketing Digital ?', 'Marketing, commerce, communication, digital, web, innovation, Social CRM, influence, Big Data, IA, trafic, analyse web, community management et référencement. Le choix doit être rapproché de votre profil et de votre projet professionnel.', 9),
